import React, { useState, useEffect } from 'react';
import API from '../utils/api';
import toast from 'react-hot-toast';

const Customers = () => {
  const [customers, setCustomers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [editingCustomer, setEditingCustomer] = useState(null);
  const [search, setSearch] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [filterPayment, setFilterPayment] = useState('all');
  const [sendingWhatsApp, setSendingWhatsApp] = useState(null);

  const [formData, setFormData] = useState({
    name: '',
    customerId: '',
    monthlyFee: '',
    pendingDues: '0',
    connectionDate: '',
    phone: '',
    status: 'Active',
    paymentStatus: 'Unpaid',
  });

  useEffect(() => {
    loadCustomers();
  }, []);

  const loadCustomers = async () => {
    try {
      setLoading(true);
      // Load customers in the order they were imported (Excel order)
      const res = await API.get('/customers?limit=1000');
      setCustomers(res.data.data);
    } catch (error) {
      toast.error('Failed to load customers');
      console.error('Error:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const resetForm = () => {
    setFormData({
      name: '',
      customerId: '',
      monthlyFee: '',
      pendingDues: '0',
      connectionDate: '',
      phone: '',
      status: 'Active',
      paymentStatus: 'Unpaid',
    });
    setEditingCustomer(null);
  };

  const openAddModal = () => {
    resetForm();
    setShowModal(true);
  };

  const openEditModal = (customer) => {
    setEditingCustomer(customer);
    setFormData({
      name: customer.name,
      customerId: customer.customerId,
      monthlyFee: customer.monthlyFee,
      pendingDues: customer.pendingDues || 0,
      connectionDate: customer.connectionDate || '',
      phone: customer.phone || '',
      status: customer.status,
      paymentStatus: customer.paymentStatus,
    });
    setShowModal(true);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      if (editingCustomer) {
        await API.put(`/customers/${editingCustomer._id}`, formData);
        toast.success('Customer updated successfully!');
      } else {
        await API.post('/customers', formData);
        toast.success('Customer added successfully!');
      }
      setShowModal(false);
      resetForm();
      loadCustomers();
    } catch (error) {
      toast.error(error.response?.data?.message || 'Operation failed');
      console.error('Error:', error);
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Are you sure you want to delete this customer?')) return;
    try {
      await API.delete(`/customers/${id}`);
      toast.success('Customer deleted successfully!');
      loadCustomers();
    } catch (error) {
      toast.error('Failed to delete customer');
      console.error('Error:', error);
    }
  };

  const sendWhatsAppReminder = async (customer) => {
    if (!customer.phone || customer.phone.trim() === '') {
      toast.error('No phone number available for this customer!');
      return;
    }

    setSendingWhatsApp(customer._id);
    try {
      const res = await API.post('/whatsapp/send', {
        customerId: customer.customerId
      });

      if (res.data.success) {
        window.open(res.data.data.whatsappUrl, '_blank');
        toast.success(`WhatsApp opened for ${customer.name}!`);
      }
    } catch (error) {
      toast.error(error.response?.data?.message || 'Failed to send reminder');
      console.error('Error:', error);
    } finally {
      setSendingWhatsApp(null);
    }
  };

  const sendBulkWhatsApp = async () => {
    const unpaid = customers.filter(c => c.paymentStatus === 'Unpaid' && c.phone);
    if (unpaid.length === 0) {
      toast.error('No unpaid customers with phone numbers found!');
      return;
    }

    if (!window.confirm(`Send WhatsApp reminders to ${unpaid.length} unpaid customers?`)) return;

    try {
      const res = await API.post('/whatsapp/bulk');
      if (res.data.success) {
        const links = res.data.data || [];
        links.slice(0, 5).forEach(item => {
          window.open(item.whatsappUrl, '_blank');
        });
        toast.success(`Opened WhatsApp for ${links.length} customers!`);
      }
    } catch (error) {
      toast.error('Failed to send bulk reminders');
      console.error('Error:', error);
    }
  };

  // Filter customers only (NO sorting)
  const filteredCustomers = customers.filter((c) => {
    const matchesSearch = c.name.toLowerCase().includes(search.toLowerCase()) ||
                          c.customerId.toLowerCase().includes(search.toLowerCase());
    const matchesStatus = filterStatus === 'all' || c.status === filterStatus;
    const matchesPayment = filterPayment === 'all' || c.paymentStatus === filterPayment;
    return matchesSearch && matchesStatus && matchesPayment;
  });

  if (loading) {
    return <div className="loading">Loading customers...</div>;
  }

  return (
    <div>
      <div style={styles.header}>
        <h2 style={styles.pageTitle}>Customers ({customers.length})</h2>
        <div style={styles.headerButtons}>
          <button style={styles.whatsappBulkBtn} onClick={sendBulkWhatsApp}>
            📱 Bulk WhatsApp
          </button>
          <button style={styles.addBtn} onClick={openAddModal}>
            ➕ Add Customer
          </button>
        </div>
      </div>

      <div style={styles.filters}>
        <input
          type="text"
          placeholder="Search by name or ID..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          style={styles.searchInput}
        />
        <select
          value={filterStatus}
          onChange={(e) => setFilterStatus(e.target.value)}
          style={styles.filterSelect}
        >
          <option value="all">All Status</option>
          <option value="Active">Active</option>
          <option value="Cut Off">Cut Off</option>
          <option value="Disable">Disable</option>
        </select>
        <select
          value={filterPayment}
          onChange={(e) => setFilterPayment(e.target.value)}
          style={styles.filterSelect}
        >
          <option value="all">All Payment</option>
          <option value="Unpaid">Unpaid</option>
          <option value="Paid">Paid</option>
          <option value="1 YEAR ADVANCED">Advanced</option>
          <option value="FREE">FREE</option>
        </select>
      </div>

      <div style={styles.tableContainer}>
        <table style={styles.table}>
          <thead>
            <tr>
              <th style={{ padding: '10px', textAlign: 'left' }}>#</th>
              <th style={{ padding: '10px', textAlign: 'left' }}>Name</th>
              <th style={{ padding: '10px', textAlign: 'left' }}>Customer ID</th>
              <th style={{ padding: '10px', textAlign: 'left' }}>Monthly Fee</th>
              <th style={{ padding: '10px', textAlign: 'left' }}>Pending Dues</th>
              <th style={{ padding: '10px', textAlign: 'left' }}>Day</th>
              <th style={{ padding: '10px', textAlign: 'left' }}>Phone</th>
              <th style={{ padding: '10px', textAlign: 'left' }}>Status</th>
              <th style={{ padding: '10px', textAlign: 'left' }}>Payment</th>
              <th style={{ padding: '10px', textAlign: 'left' }}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {filteredCustomers.length === 0 ? (
              <tr><td colSpan="10" style={{ textAlign: 'center', padding: '30px', color: '#6b7f99' }}>No customers found</td></tr>
            ) : (
              filteredCustomers.map((c, index) => (
                <tr key={c._id}>
                  <td style={{ padding: '10px' }}>{index + 1}</td>
                  <td style={{ padding: '10px' }}><strong>{c.name}</strong></td>
                  <td style={{ padding: '10px' }}>{c.customerId}</td>
                  <td style={{ padding: '10px' }}>PKR {c.monthlyFee.toLocaleString()}</td>
                  <td style={{ padding: '10px', color: c.pendingDues > 0 ? '#dc3545' : '#6b7f99' }}>
                    {c.pendingDues > 0 ? `PKR ${c.pendingDues.toLocaleString()}` : '—'}
                  </td>
                  <td style={{ padding: '10px', fontWeight: '700', color: '#2a7de1', fontSize: '18px' }}>
                    {c.connectionDate || '—'}
                  </td>
                  <td style={{ padding: '10px' }}>
                    {c.phone ? (
                      <span style={styles.phoneDisplay}>
                        {c.phone}
                        <button
                          style={styles.whatsappBtn}
                          onClick={() => sendWhatsAppReminder(c)}
                          disabled={sendingWhatsApp === c._id}
                          title="Send WhatsApp reminder"
                        >
                          {sendingWhatsApp === c._id ? '⏳' : '📱'}
                        </button>
                      </span>
                    ) : (
                      <span style={{ color: '#999', fontSize: '12px' }}>No phone</span>
                    )}
                  </td>
                  <td style={{ padding: '10px' }}>
                    <span style={{
                      ...styles.statusBadge,
                      background: c.status === 'Active' ? '#d4edda' : c.status === 'Cut Off' ? '#f8d7da' : '#e2e3e5',
                      color: c.status === 'Active' ? '#155724' : c.status === 'Cut Off' ? '#721c24' : '#383d41',
                    }}>
                      {c.status}
                    </span>
                  </td>
                  <td style={{ padding: '10px' }}>
                    <span style={{
                      ...styles.statusBadge,
                      background: c.paymentStatus === 'Paid' ? '#d4edda' : c.paymentStatus === '1 YEAR ADVANCED' ? '#cce5ff' : c.paymentStatus === 'FREE' ? '#e2e3e5' : '#f8d7da',
                      color: c.paymentStatus === 'Paid' ? '#155724' : c.paymentStatus === '1 YEAR ADVANCED' ? '#004085' : c.paymentStatus === 'FREE' ? '#383d41' : '#721c24',
                    }}>
                      {c.paymentStatus}
                    </span>
                  </td>
                  <td style={{ padding: '10px' }}>
                    <button style={styles.actionBtn} onClick={() => openEditModal(c)}>✏️</button>
                    <button style={{ ...styles.actionBtn, color: '#dc3545' }} onClick={() => handleDelete(c._id)}>🗑️</button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {showModal && (
        <div style={styles.modalOverlay} onClick={() => setShowModal(false)}>
          <div style={styles.modal} onClick={(e) => e.stopPropagation()}>
            <h3 style={styles.modalTitle}>
              {editingCustomer ? '✏️ Edit Customer' : '➕ Add New Customer'}
            </h3>
            <form onSubmit={handleSubmit}>
              <div style={styles.formGrid}>
                <div style={styles.formGroup}>
                  <label style={styles.label}>Name *</label>
                  <input
                    type="text"
                    name="name"
                    value={formData.name}
                    onChange={handleInputChange}
                    style={styles.input}
                    required
                  />
                </div>
                <div style={styles.formGroup}>
                  <label style={styles.label}>Customer ID *</label>
                  <input
                    type="text"
                    name="customerId"
                    value={formData.customerId}
                    onChange={handleInputChange}
                    style={styles.input}
                    required
                  />
                </div>
                <div style={styles.formGroup}>
                  <label style={styles.label}>Monthly Fee (PKR) *</label>
                  <input
                    type="number"
                    name="monthlyFee"
                    value={formData.monthlyFee}
                    onChange={handleInputChange}
                    style={styles.input}
                    required
                  />
                </div>
                <div style={styles.formGroup}>
                  <label style={styles.label}>Pending Dues</label>
                  <input
                    type="number"
                    name="pendingDues"
                    value={formData.pendingDues}
                    onChange={handleInputChange}
                    style={styles.input}
                  />
                </div>
                <div style={styles.formGroup}>
                  <label style={styles.label}>Day (1-31)</label>
                  <input
                    type="text"
                    name="connectionDate"
                    value={formData.connectionDate}
                    onChange={handleInputChange}
                    placeholder="e.g., 15"
                    style={styles.input}
                  />
                </div>
                <div style={styles.formGroup}>
                  <label style={styles.label}>Phone Number</label>
                  <input
                    type="text"
                    name="phone"
                    value={formData.phone}
                    onChange={handleInputChange}
                    placeholder="e.g., 0300-1234567"
                    style={styles.input}
                  />
                </div>
                <div style={styles.formGroup}>
                  <label style={styles.label}>Status</label>
                  <select
                    name="status"
                    value={formData.status}
                    onChange={handleInputChange}
                    style={styles.input}
                  >
                    <option value="Active">Active</option>
                    <option value="Cut Off">Cut Off</option>
                    <option value="Disable">Disable</option>
                  </select>
                </div>
                <div style={styles.formGroup}>
                  <label style={styles.label}>Payment Status</label>
                  <select
                    name="paymentStatus"
                    value={formData.paymentStatus}
                    onChange={handleInputChange}
                    style={styles.input}
                  >
                    <option value="Unpaid">Unpaid</option>
                    <option value="Paid">Paid</option>
                    <option value="1 YEAR ADVANCED">1 YEAR ADVANCED</option>
                    <option value="FREE">FREE</option>
                  </select>
                </div>
              </div>
              <div style={styles.modalActions}>
                <button type="button" style={styles.cancelBtn} onClick={() => setShowModal(false)}>Cancel</button>
                <button type="submit" style={styles.saveBtn}>
                  {editingCustomer ? 'Update' : 'Add'} Customer
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

